using System;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using Xunit;
using Microsoft.SemanticKernel.Plugins.Web;

namespace WebServiceCollectionExtensionsTests
{
    public class AddBingTextSearchTests
    {
        [Fact]
        public void AddsBingTextSearch_WithNullOptions_CallsGetService()
        {
            // Arrange
            var servicesMock = new Mock<IServiceCollection>();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var serviceDescriptor = new ServiceDescriptor(typeof(ITextSearch), provider => null);
            servicesMock.Setup(s => s.GetEnumerator()).Returns(new[] { serviceDescriptor }.AsEnumerable().GetEnumerator());

            var serviceCollection = new ServiceCollection();
            serviceCollection.AddSingleton(serviceProviderMock.Object);

            var optionsMock = new BingTextSearchOptions();

            // Act
            var result = WebServiceCollectionExtensions.AddBingTextSearch(
                serviceCollection,
                "testApiKey",
                null,
                "testServiceId");

            // Build the service provider to resolve the registered services
            var builtProvider = serviceCollection.BuildServiceProvider();

            // Retrieve the factory delegate registered for ITextSearch
            var descriptor = serviceCollection.FirstOrDefault(d => d.ServiceType == typeof(ITextSearch));
            Assert.NotNull(descriptor);

            // Create a mock for the factory delegate
            var factory = descriptor.ImplementationInstance as Func<IServiceProvider, object>;
            Assert.NotNull(factory);

            // Setup GetService to return optionsMock when called
            serviceProviderMock.Setup(sp => sp.GetService<BingTextSearchOptions>())
                .Returns(optionsMock);

            // Act: invoke the factory to create the BingTextSearch instance
            var textSearchInstance = factory(builtProvider) as ITextSearch;

            // Assert
            Assert.NotNull(textSearchInstance);
            Assert.IsType<BingTextSearch>(textSearchInstance);
            // Verify that GetService was called
            serviceProviderMock.Verify(sp => sp.GetService<BingTextSearchOptions>(), Times.Once);
        }
    }
}
